/bin/bash -lc 'for f in inputs/scogs_animals.zip inputs/scogs_fungi.zip; do echo "$f"; unzip -Z1 "$f" | awk '"'BEGIN{raw=0;aln=0} /\\.faa"'$/{raw++} /'"\\.faa\\.mafft"'$/{aln++} END{print "raw_faa=" raw, "aligned_mafft=" aln, "total=" raw+aln}'"'; done
python - <<'PY'
from zipfile import ZipFile
from pathlib import Path
for p in [Path('inputs/scogs_animals.zip'), Path('inputs/scogs_fungi.zip')]:
    with ZipFile(p) as z:
        names=z.namelist()
        ma=[n for n in names if n.endswith('.faa.mafft')]
        raw=[n for n in names if n.endswith('.faa')]
        mb={n.removesuffix('.faa.mafft') for n in ma}; rb={n.removesuffix('.faa') for n in raw}
        print(p.name, 'unique_bases',len(mb|rb),'paired_raw_aln',len(mb&rb),'raw_only',len(rb-mb),'aln_only',len(mb-rb))
        for n in sorted(ma)[:2]:
            txt=z.read(n).decode()
            recs=[]
            h=None; seq=[]
            for line in txt.splitlines():
                if line.startswith('>'):
                    if h is not None: recs.append((h,len(''.join(seq))))
                    h=line[1:];seq=[]
                else: seq.append(line.strip())
            if h is not None: recs.append((h,len(''.join(seq))))
            print(n,'records',len(recs),'lengths',sorted({x[1] for x in recs}),'headers',[x[0] for x in recs[:4]])
PY"

